package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.Base64Variant;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class UTF8JsonGenerator_writeBinary_TriageGen0Test {

    private IOContext context;
    private OutputStream outputStream;
    private UTF8JsonGenerator generator;

    @Before
    public void setUp() {
        context = new IOContext();
        outputStream = new java.io.ByteArrayOutputStream();
        // Using the constructor provided in the prompt
        generator = new UTF8JsonGenerator(context, 0, null, outputStream);
    }

    @Test
    public void testWriteBinary_WithKnownLength_Success() throws IOException {
        byte[] data = {0x01, 0x02, 0x03, 0x04};
        InputStream inputStream = new ByteArrayInputStream(data);
        int dataLength = data.length;

        int bytesWritten = generator.writeBinary(Base64Variant.of(""), inputStream, dataLength);

        Assert.assertEquals(dataLength, bytesWritten);
        // Verify output contains quotes (Base64 encoding of 01 02 03 04 is AQIDBA==)
        String output = outputStream.toString();
        Assert.assertTrue(output.contains("\""));
        Assert.assertTrue(output.contains("AQIDBA=="));
    }

    @Test
    public void testWriteBinary_WithUnknownLength() throws IOException {
        byte[] data = {0x01, 0x02, 0x03, 0x04};
        InputStream inputStream = new ByteArrayInputStream(data);
        int dataLength = -1; // Unknown length

        int bytesWritten = generator.writeBinary(Base64Variant.of(""), inputStream, dataLength);

        // When length is unknown, it returns the actual bytes read (which should be 4)
        Assert.assertEquals(4, bytesWritten);
        String output = outputStream.toString();
        Assert.assertTrue(output.contains("\""));
        Assert.assertTrue(output.contains("AQIDBA=="));
    }

    @Test(expected = IOException.class)
    public void testWriteBinary_WithTooFewBytes_ThrowsException() throws IOException {
        byte[] data = {0x01, 0x02};
        InputStream inputStream = new ByteArrayInputStream(data);
        int dataLength = 4; // We claim 4 bytes, but only 2 are available

        // This should trigger _reportError which throws an IOException
        generator.writeBinary(Base64Variant.of(""), inputStream, dataLength);
    }

    @Test
    public void testWriteBinary_TriggersFlush() throws IOException {
        // To test the _outputTail >= _outputEnd branch, we need a very small buffer or 
        // many writes. Since we can't easily control the internal buffer size via the public API 
        // without reflection, we perform multiple writes to fill it.

        byte[] data = {0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17};
        InputStream inputStream = new ByteArrayInputStream(data);

        // Write multiple times to ensure _outputTail reaches _outputEnd
        for (int i = 0; i < 100; i++) {
            generator.writeBinary(Base64Variant.of(""), inputStream, data.length);
            inputStream.reset();
        }

        generator.flush();
        String output = outputStream.toString();
        Assert.assertFalse(output.isEmpty());
    }

    @Test
    public void testWriteBinary_EmptyInputStream_KnownLength() throws IOException {
        byte[] data = new byte[0];
        InputStream inputStream = new ByteArrayInputStream(data);
        int dataLength = 0;

        int bytesWritten = generator.writeBinary(Base64Variant.of(""), inputStream, dataLength);

        Assert.assertEquals(0, bytesWritten);
        // Output should just be the quotes for an empty binary field: ""
        String output = outputStream.toString();
        Assert.assertEquals("\"\"", output);
    }

    @Test(expected = IOException.class)
    public void testWriteBinary_InputStreamThrows() throws IOException {
        InputStream errorStream = new InputStream() {
            @Override
            public int read() throws IOException {
                throw new IOException("Simulated error");
            }
        };

        generator.writeBinary(Base64Variant.of(""), errorStream, 4);
    }
}
